require_once __DIR__.'/includes/config.php';
require_once __DIR__.'/includes/api.php';

// Detaliile voucherului emis vin din pasul de cumpărare prin query params.
// Fallback pe valorile demo dacă lipsesc (pagina rămâne funcțională standalone).
$gcCode     = trim($_GET['code'] ?? '') ?: 'NORD-8Q2L-5MT7';
$gcAmount   = isset($_GET['amount']) && is_numeric($_GET['amount']) ? (float) $_GET['amount'] : 350;
$gcTo       = trim($_GET['to'] ?? '') ?: 'Mara';
$gcToFull   = trim($_GET['to_full'] ?? '') ?: ($gcTo !== 'Mara' ? $gcTo : 'Mara Pop');
$gcEmail    = trim($_GET['email'] ?? '') ?: 'mara@example.ro';
$gcMsg      = trim($_GET['msg'] ?? ($_GET['message'] ?? '')) ?: 'Pentru o zi cu aer curat, curaj și libertate. Să alegi aventura care te face să uiți de timp.';
$gcFrom     = trim($_GET['from'] ?? '') ?: 'andrei@example.ro';
$gcOrder    = trim($_GET['order'] ?? '') ?: 'NV-GIFT-2041';
$gcAmountFmt = price_fmt($gcAmount, 'RON');
?>
