<script>
(() => {
  'use strict';
  const $ = (s, root=document) => root.querySelector(s);
  const $$ = (s, root=document) => [...root.querySelectorAll(s)];
  const state = { scheduled: true, email:'<?= e($gcEmail) ?>', date:'2026-08-18', time:'08:00' };
  let toastTimer;
  function toast(message){ const el=$('#toast'); if(!el)return; el.textContent=message; el.classList.add('show'); clearTimeout(toastTimer); toastTimer=setTimeout(()=>el.classList.remove('show'),2600); }
  function openModal(id){ const el=$(id); if(!el)return; el.classList.add('open'); el.setAttribute('aria-hidden','false'); document.body.style.overflow='hidden'; setTimeout(()=>el.querySelector('input,button,textarea,select')?.focus(),50); }
  function closeModal(el){ if(!el)return; el.classList.remove('open'); el.setAttribute('aria-hidden','true'); document.body.style.overflow=''; }
  function formatDate(value){ const d=new Date(value+'T12:00:00'); return new Intl.DateTimeFormat('ro-RO',{day:'numeric',month:'short',year:'numeric'}).format(d); }
  function updateDeliveryUI(){
    const title=$('#deliveryTitle'), copy=$('#deliveryCopy'), badge=$('#deliveryBadge'), dateLabel=$('#deliveryDateLabel'), emailLabel=$('#recipientEmailLabel'), timeline=$('#timelineDeliveryCopy'), mobile=$('#mobileDeliveryText'), step=$('#timelineDelivery');
    if(state.scheduled){
      title.textContent='Email programat pentru '+formatDate(state.date).replace('2026','').trim();
      copy.textContent=`Voucherul va ajunge la ${state.email} la ora ${state.time}. Până atunci poți modifica momentul livrării sau îl poți trimite personal.`;
      badge.textContent='Programată'; dateLabel.textContent=`${formatDate(state.date)} · ${state.time}`; timeline.textContent=`${formatDate(state.date)} · ${state.time}`; mobile.textContent=`Livrare ${formatDate(state.date).replace('2026','').trim()} · ${state.time}`; step.classList.add('future');
    } else {
      title.textContent='Voucher trimis către <?= e($gcTo) ?>'; copy.textContent=`Emailul a fost trimis la ${state.email}. Poți retrimite voucherul sau îl poți distribui printr-un alt canal.`;
      badge.textContent='Trimis'; dateLabel.textContent='Trimis acum'; timeline.textContent='Trimis către '+state.email; mobile.textContent='Voucher trimis'; step.classList.remove('future');
    }
    emailLabel.textContent=state.email;
  }
  function downloadFile(name, content, type='text/plain'){ const blob=new Blob([content],{type}); const url=URL.createObjectURL(blob); const a=document.createElement('a'); a.href=url; a.download=name; document.body.appendChild(a); a.click(); a.remove(); setTimeout(()=>URL.revokeObjectURL(url),500); }
  function downloadVoucher(){
    const svg=`<svg xmlns="http://www.w3.org/2000/svg" width="1400" height="900" viewBox="0 0 1400 900"><defs><linearGradient id="g" x1="0" y1="0" x2="1" y2="1"><stop stop-color="#173e32"/><stop offset="1" stop-color="#09231c"/></linearGradient></defs><rect width="1400" height="900" rx="60" fill="url(#g)"/><circle cx="1180" cy="160" r="250" fill="#dffc62" opacity=".12"/><circle cx="190" cy="760" r="210" fill="#f27b4a" opacity=".12"/><text x="85" y="105" fill="#fff" font-family="Georgia" font-size="50">Nordvale</text><text x="85" y="320" fill="#dffc62" font-family="Arial" font-weight="700" font-size="25" letter-spacing="5">PENTRU</text><text x="85" y="440" fill="#fff" font-family="Georgia" font-size="110"><?= e($gcTo) ?></text><text x="85" y="535" fill="#fff" opacity=".72" font-family="Arial" font-size="28">Pentru o zi cu aer curat, curaj și libertate.</text><text x="85" y="720" fill="#fff" opacity=".55" font-family="Arial" font-size="23" letter-spacing="3">VOUCHER VALORIC</text><text x="85" y="805" fill="#fff" font-family="Georgia" font-size="72"><?= e($gcAmountFmt) ?></text><rect x="990" y="740" width="320" height="70" rx="20" fill="#dffc62" opacity=".12" stroke="#dffc62" stroke-opacity=".35"/><text x="1030" y="786" fill="#dffc62" font-family="monospace" font-size="30" letter-spacing="4"><?= e($gcCode) ?></text></svg>`;
    downloadFile('voucher-nordvale-mara.svg',svg,'image/svg+xml'); toast('Voucherul a fost descărcat.');
  }
  $('#menuOpen')?.addEventListener('click',()=>$('#mobileMenu')?.classList.add('open'));
  $('#menuClose')?.addEventListener('click',()=>$('#mobileMenu')?.classList.remove('open'));
  ['#shareOpen','#shareOpen2'].forEach(id=>$(id)?.addEventListener('click',()=>openModal('#shareModal')));
  $('#editDeliveryOpen')?.addEventListener('click',()=>openModal('#deliveryModal'));
  $$('[data-close-modal]').forEach(btn=>btn.addEventListener('click',()=>closeModal(btn.closest('.modal-backdrop'))));
  $$('.modal-backdrop').forEach(backdrop=>backdrop.addEventListener('click',e=>{if(e.target===backdrop)closeModal(backdrop)}));
  document.addEventListener('keydown',e=>{if(e.key==='Escape')$$('.modal-backdrop.open').forEach(closeModal)});
  $('#copyCode')?.addEventListener('click',async()=>{try{await navigator.clipboard.writeText($('#voucherCode').textContent.trim());toast('Codul voucherului a fost copiat.')}catch{toast('Selectează și copiază manual codul.')}});
  ['#downloadVoucher','#mobileDownload'].forEach(id=>$(id)?.addEventListener('click',downloadVoucher));
  $('#printVoucher')?.addEventListener('click',()=>window.print());
  $('#downloadReceipt')?.addEventListener('click',()=>{downloadFile('confirmare-comanda-<?= e($gcOrder) ?>.txt','NORDVALE\nComanda #<?= e($gcOrder) ?>\nVoucher valoric: <?= e($gcAmountFmt) ?>\nDestinatar: <?= e($gcToFull) ?>\nCod: <?= e($gcCode) ?>\nTotal plătit: <?= e($gcAmountFmt) ?>\n');toast('Confirmarea a fost descărcată.')} );
  $('#invoiceDownload')?.addEventListener('click',()=>{downloadFile('factura-NVF-2041.txt','FACTURĂ DEMO NVF-2041\nVoucher cadou Nordvale: <?= e($gcAmountFmt) ?>\nTotal: <?= e($gcAmountFmt) ?>\nPlată: card •••• 4242\n');toast('Factura demonstrativă a fost descărcată.')} );
  $('#sendNow')?.addEventListener('click',()=>{state.scheduled=false;updateDeliveryUI();toast('Voucherul a fost trimis acum către <?= e($gcTo) ?>.');});
  $('#deliveryForm')?.addEventListener('submit',e=>{e.preventDefault();const email=$('#deliveryEmail').value.trim(),date=$('#deliveryDate').value,time=$('#deliveryTime').value;if(!email||!date||!time){toast('Completează toate datele de livrare.');return}state.email=email;state.date=date;state.time=time;state.scheduled=true;updateDeliveryUI();closeModal($('#deliveryModal'));toast('Livrarea programată a fost actualizată.');});
  $('#shareForm')?.addEventListener('submit',e=>{e.preventDefault();const email=$('#shareEmail').value.trim();if(!email){toast('Completează adresa de email.');return}if($('#cancelScheduled').checked){state.email=email;state.scheduled=false;updateDeliveryUI()}closeModal($('#shareModal'));toast('Voucherul a fost trimis către '+email+'.');});
  updateDeliveryUI();
})();
</script>
</body>
</html>
